// Arma la alerta en espanol: que flujo fallo, en que nodo, el error, la hora y una pista de diagnostico.
function armarAlerta(e, ahoraISO) {
  const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const ex = (e && e.execution) || {};
  const wf = (e && e.workflow) || {};
  const err = ex.error || {};
  const flujo = wf.name || 'desconocido';
  const nodo = (err.node && err.node.name) || ex.lastNodeExecuted || 'desconocido';
  const mensaje = (String(err.message || 'sin mensaje') + (err.description ? ' | ' + err.description : '')).replace(/\s+/g, ' ').slice(0, 400);
  const t = (nodo + ' ' + mensaje).toLowerCase();

  let pista = 'Abre la ejecucion en n8n y mira el nodo que fallo.';
  if (/insufficient_credits|\b402\b/.test(t)) pista = 'Se acabaron los creditos de JEV (o no alcanzan). Recarga en jevmodel.org/pricing.';
  else if (/\b401\b|unauthorized|invalid api key|missing or invalid api key|authentication/.test(t) && /jev/.test(t)) pista = 'La llave de JEV es invalida o vencio. Renueva la credencial "jev" en n8n > Credentials.';
  else if (/pregunta_a_jev|jevmodel/.test(t)) pista = 'Fallo la llamada a JEV. Revisa la credencial "jev" en n8n y si quedan creditos.';
  else if (/\b429\b|too many requests|rate limit/.test(t)) pista = 'Demasiadas peticiones seguidas. Espera un minuto y vuelve a correr.';
  else if (/lee_hoja|guarda_bitacora|crea_ordenes|sheets\.googleapis|spreadsheet|google/.test(t)) pista = 'Fallo Google Sheets. Revisa que la hoja jev_inventario_demo exista, que sus pestanas no cambiaron de nombre y que la credencial "Google Sheets account" siga viva.';
  else if (/telegram|chat not found|bot was blocked/.test(t)) pista = 'Fallo Telegram. Revisa el bot tu bot de Telegram (dale Iniciar) y la credencial tu credencial de Telegram.';
  else if (/timeout|etimedout|econnreset|econnrefused|socket hang up/.test(t)) pista = 'Se corto la conexion o tardo demasiado. Vuelve a correr; si se repite, revisa el servicio.';
  else if (/connection cannot be established|incorrect host|enotfound|getaddrinfo/.test(t)) pista = 'No se pudo conectar: la direccion (URL) del servicio esta mal escrita o el servicio no existe. Revisa la URL del nodo que fallo.';
  else if (/typeerror|referenceerror|syntaxerror|cannot read properties|is not defined/.test(t)) pista = 'Error de codigo en un nodo Code. Abre el nodo senalado y revisa la linea.';
  else if (/pestana .* vacia|no hay productos activos|no hay ningun producto/.test(t)) pista = 'La hoja esta vacia o sin productos activos. Corre inventario_reinicia_demo.';

  let texto = '<b>ALERTA · Decide Inventario</b>\n';
  texto += 'Fallo el flujo <b>' + esc(flujo) + '</b> en el nodo <b>' + esc(nodo) + '</b>\n\n';
  texto += 'Error: ' + esc(mensaje) + '\n\n';
  texto += 'Pista: ' + esc(pista) + '\n';
  texto += '\nSi fue durante un analisis, puede que el resumen de decisiones no haya llegado: revisa la pestana decisiones de la hoja.\n';
  texto += '\nHora: ' + esc(ahoraISO);
  if (ex.url) texto += '\nEjecucion: ' + esc(ex.url);
  return { texto, flujo, nodo, mensaje, pista };
}
return [{ json: armarAlerta($input.first().json, new Date().toISOString()) }];
